INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cf0a6f6d-f0ec-461f-ac6b-57cbf94b2cf6', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which Cisco protocol provides first-hop redundancy (variant 2).', '[{"id": "A", "text": "HSRP", "is_correct": true}, {"id": "B", "text": "STP", "is_correct": false}, {"id": "C", "text": "CDP", "is_correct": false}, {"id": "D", "text": "LLDP", "is_correct": false}]', 'HSRP (Hot Standby Router Protocol) is Cisco''s FHRP that provides default gateway redundancy by allowing two or more routers to share a virtual IP and MAC address (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipapp_fhrp/"}', 'First Hop Redundancy', 12.0, '82f712596fb7cce7_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5e29862d-5001-4e67-a166-ecd60651f53b', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'What does VLAN 1 represent on a Cisco switch by default (variant 2).', '[{"id": "A", "text": "The default management VLAN - all ports belong to VLAN 1", "is_correct": true}, {"id": "B", "text": "A reserved VLAN for voice traffic", "is_correct": false}, {"id": "C", "text": "A native VLAN for trunk ports only", "is_correct": false}, {"id": "D", "text": "An unused VLAN for security isolation", "is_correct": false}]', 'By default, all switch ports are in VLAN 1, which also carries management traffic including CDP, VTP, PAgP, and DTP (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'VLAN', 12.0, 'bb923c9150e0cf19_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('af44ae83-c8cb-458b-9392-66faba9e969d', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of DTP (Dynamic Trunking Protocol) on Cisco switches (variant 2).', '[{"id": "A", "text": "Automatically negotiates trunking mode between connected switches", "is_correct": true}, {"id": "B", "text": "Dynamically assigns VLANs to access ports", "is_correct": false}, {"id": "C", "text": "Detects topology changes in the network", "is_correct": false}, {"id": "D", "text": "Provides authentication between switches", "is_correct": false}]', 'DTP is a Cisco proprietary protocol that negotiates the trunking mode (access/trunk/dynamic) between two connected switch interfaces (Variant 2).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'Trunking', 12.0, 'b70a3636d1363704_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9b56d259-d494-4c76-a3a2-ade3aff6c9e9', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'Which IPv6 address type is equivalent to a private IPv4 address (variant 3).', '[{"id": "A", "text": "Unique Local (fc00::/7)", "is_correct": true}, {"id": "B", "text": "Link-Local (fe80::/10)", "is_correct": false}, {"id": "C", "text": "Global Unicast (2000::/3)", "is_correct": false}, {"id": "D", "text": "Multicast (ff00::/8)", "is_correct": false}]', 'Unique Local Unicast addresses (fc00::/7) are the IPv6 equivalent of RFC 1918 private addresses. They are not globally routable (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ipv6/"}', 'IPv6', 12.0, 'aed920ac155c5704_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('db12c660-fddd-4ae0-bbaa-01f06fab51be', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 2, 'understand', 'What is the purpose of the ''spanning-tree portfast'' command on a Cisco switch (variant 3).', '[{"id": "A", "text": "Bypasses the listening and learning states for access ports", "is_correct": true}, {"id": "B", "text": "Enables rapid STP on the port", "is_correct": false}, {"id": "C", "text": "Disables STP on the port", "is_correct": false}, {"id": "D", "text": "Configures the port as a trunk", "is_correct": false}]', 'PortFast immediately transitions a port from blocking to forwarding state, bypassing listening and learning. Used only on access ports connected to end hosts (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/lanswitch/"}', 'STP', 12.0, 'd48876a6a45136da_gen_v3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa6e35b8-4124-45b4-bac1-f62bf8171603', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 1, 'remember', 'Which routing protocol is considered link-state (variant 3).', '[{"id": "A", "text": "OSPF", "is_correct": true}, {"id": "B", "text": "RIP", "is_correct": false}, {"id": "C", "text": "EIGRP", "is_correct": false}, {"id": "D", "text": "BGP", "is_correct": false}]', 'OSPF (Open Shortest Path First) is a link-state routing protocol. It maintains a complete view of the network topology using LSAs (Variant 3).', '{"https://www.cisco.com/c/en/us/td/docs/ios-xml/ios/ospf/"}', 'Routing Protocols', 12.0, '9f0cda122bf8f46c_gen_v3', true) ON CONFLICT (id) DO NOTHING;

